    tx(g3, w - 2, by - 8, '观察者的推断', 'fx-n fx-r fx-halo', 'end');
    tx(g2, 2, th + 30, '常被忽视', 'fx-n fx-halo');
    const g4 = el('g', {}, s); gs.push(g4);
